/**
 * Cloudflare Worker entry for Revel.
 *
 * Wraps the Worker generated by `opennextjs-cloudflare build` so the single
 * application Worker can also export:
 * - `AuditWorkflow` — durable audit execution (Cloudflare Workflows), and
 * - `scheduled` — the daily IndexNow re-index cron (formerly a Vercel cron).
 *
 * Every HTTP request is still served by the unchanged OpenNext handler.
 */

// Generated at build time by `opennextjs-cloudflare build`.
// @ts-expect-error -- resolved by Wrangler when bundling the build output.
import { default as openNextWorker } from "../.open-next/worker.js";
import type { RevelWorkerEnv } from "./env";

export { AuditWorkflow } from "./audit-workflow";

/** wrangler.jsonc → triggers.crons. Daily at 06:00 UTC (unchanged from Vercel). */
const INDEXNOW_CRON = "0 6 * * *";

const INTERNAL_ORIGIN = "https://revel-cron.internal";

async function runIndexNow(env: RevelWorkerEnv): Promise<void> {
  if (env.INDEXNOW_DISABLED === "true") {
    console.log("[Revel] indexnow cron skipped (INDEXNOW_DISABLED=true)");
    return;
  }
  // Fail closed: /api/indexnow rejects unauthenticated production calls.
  if (!env.CRON_SECRET) {
    console.error("[Revel] indexnow cron skipped: CRON_SECRET is not set");
    return;
  }
  if (!env.WORKER_SELF_REFERENCE) {
    console.error("[Revel] indexnow cron skipped: WORKER_SELF_REFERENCE missing");
    return;
  }

  const response = await env.WORKER_SELF_REFERENCE.fetch(
    `${INTERNAL_ORIGIN}/api/indexnow`,
    { method: "GET", headers: { Authorization: `Bearer ${env.CRON_SECRET}` } }
  );
  const body = await response.text();
  const line = JSON.stringify({
    level: response.ok ? "info" : "error",
    source: "revel",
    scope: "indexnow_cron",
    status: response.status,
    body: body.slice(0, 500),
  });
  if (response.ok) console.log(line);
  else console.error(line);
}

export default {
  fetch: openNextWorker.fetch,

  async scheduled(controller, env, ctx) {
    if (controller.cron === INDEXNOW_CRON) {
      ctx.waitUntil(runIndexNow(env));
      return;
    }
    console.warn(`[Revel] unknown cron trigger: ${controller.cron}`);
  },
} satisfies ExportedHandler<RevelWorkerEnv>;
